mapper.select:
select

ad.Ad_Name as adName,
mn.*
from  Archive mn
left join Archive_Directory ad on ad.Ad_Id=mn.Ad_Id

${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id =#{params.pId}


    and mn.Ad_Id =#{params.adId}


    and mn.Ap_State=#{params.apState}


    and pro.P_Name like concat('%',#{params.pName},'%')


    and mn.Ap_Keyword like concat('%',#{params.apKeyword},'%')


    and mn.Ap_Title like concat('%',#{params.apTitle},'%')


    and mn.Ap_Author like concat('%',#{params.apAuthor},'%')


    and mn.Ap_Document_No like concat('%',#{params.apDocumentNo},'%')


    and mn.Ap_Receipt_No like concat('%',#{params.apReceiptNo},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ap_Desc_Create_Time DESC
